import React from 'react';
import { connect } from 'react-redux';
import moment from 'moment';
import { Row, Col } from 'reactstrap';
import EditIcon from '@material-ui/icons/Edit';
import KeyboardArrowDownIcon from '@material-ui/icons/KeyboardArrowDown';
import KeyboardArrowUpIcon from '@material-ui/icons/KeyboardArrowUp';
import IconButton from '@material-ui/core/IconButton';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableContainer from '@material-ui/core/TableContainer';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import Collapse from '@material-ui/core/Collapse';
import { Paper, Typography } from '@material-ui/core';
import Skeleton from '@material-ui/lab/Skeleton';
import { fetchSchoolEmployeesApi } from '../../../actions/admin/employees';
import { fetchAttendanceRangeService, fetchAttendanceReportService } from '../../../actions/admin/attendance';
import { fetchAttendanceConfigService } from '../../../actions/admin/config';
import { getGlobalSchoolUtils, getLocalStore, setLocalStore, formEmpSelectList } from '../../../utils/commonFunc';
import MuiTable from '../Common/MuiTable.jsx';
import CustomButton from '../../../components/CustomButton.jsx';
import CustomSelect from '../../../components/CustomSelect.jsx';
import colors from '../../../config/colors';
import AttendanceEditModal from './components/AttendanceEditModal.jsx';
import { downloadCsv } from './staffAttendanceUtils.js';
import CommonTooltip from '../Common/CommonTooltip.jsx';
import EmptyState from '../Common/EmptyState.jsx';
import StatTile from '../Common/StatTile.jsx';
import PeopleOutlineIcon from '@material-ui/icons/PeopleOutline';

// Annual was folded into Monthly - a From/To month range now spans anywhere from one month to
// three years (see MAX_MONTH_SPAN), so there's no need for a separate "whole year" mode. Both
// still ride the same report endpoint call (DATE_RANGE) regardless of span length.
const REPORT_VIEWS = [
  { key: 'daily', label: 'Daily' },
  { key: 'weekly', label: 'Weekly' },
  { key: 'monthly', label: 'Monthly' },
];

const MIN_WEEK_SPAN_DAYS = 7;
const MAX_WEEK_SPAN_DAYS = 21;
const MAX_MONTH_SPAN = 36; // 3 years - capped so a report can't be asked to load unbounded data.

const formatTime = time => (time ? moment(time, 'HH:mm:ss').format('hh:mm A') : '--');

// Teacher and Worker Attendance are separate mounted instances of this component (see
// StaffAttendanceHubPage), so each needs its own stored view mode/selected employee, not one
// shared key.
const viewModeStoreKey = roleFilter => `staffAttendanceViewMode_${roleFilter}`;
const employeeStoreKey = roleFilter => `staffAttendanceEmployee_${roleFilter}`;

const storedViewMode = roleFilter => {
  const stored = getLocalStore(viewModeStoreKey(roleFilter));
  return REPORT_VIEWS.some(view => view.key === stored) ? stored : 'daily';
};

const defaultWeekRange = () => ({
  fromDate: moment().subtract(6, 'days').format('YYYY-MM-DD'),
  toDate: moment().format('YYYY-MM-DD'),
});

const defaultMonthRange = () => {
  const thisMonth = moment().format('YYYY-MM');
  return { fromMonth: thisMonth, toMonth: thisMonth };
};

const weekSpanDays = (fromDate, toDate) => moment(toDate).diff(moment(fromDate), 'days') + 1;
const monthSpanCount = (fromMonth, toMonth) =>
  moment(toMonth, 'YYYY-MM').diff(moment(fromMonth, 'YYYY-MM'), 'months') + 1;
const maxWeekToDate = fromDate =>
  moment(fromDate)
    .add(MAX_WEEK_SPAN_DAYS - 1, 'days')
    .format('YYYY-MM-DD');
const minWeekToDate = fromDate =>
  moment(fromDate)
    .add(MIN_WEEK_SPAN_DAYS - 1, 'days')
    .format('YYYY-MM-DD');
const maxMonthToMonth = fromMonth =>
  moment(fromMonth, 'YYYY-MM')
    .add(MAX_MONTH_SPAN - 1, 'months')
    .format('YYYY-MM');

// Renders one role's attendance (Teacher or Worker) - the daily/weekly/monthly report and the
// admin edit modal. Mounted as one of StaffAttendanceHubPage's flat sibling tabs (Teacher
// Attendance / Worker Attendance / Staff Time Allowance); owns no page-level chrome (title
// banner, tab bar) of its own.
class StaffAttendanceRolePanel extends React.Component {
  state = {
    schoolId: 0,
    selectedDate: new Date(),
    viewMode: storedViewMode(this.props.roleFilter),
    isLoading: false,
    editModalOpen: false,
    editEmployee: null,
    attendanceConfiguration: null,
    // Server-computed summary for weekly/monthly (see fetchAttendance) - null for daily, which
    // still reads from attendanceRange (the report endpoint's DTOs carry no
    // employeeDailyAttendanceId, so editing a session needs the raw range record instead).
    reportData: null,
    weekRange: defaultWeekRange(),
    monthRange: defaultMonthRange(),
    // Monthly is scoped to one employee - Weekly (like Daily) stays whole-school. Persisted per
    // role so it survives switching between Daily/Weekly/Monthly.
    selectedEmployeeId: getLocalStore(employeeStoreKey(this.props.roleFilter)) || null,
    // Fetched into local state, not the shared state.employees.employeeList redux slice - Teacher
    // and Worker Attendance are separate mounted instances of this component that each fetch a
    // different profession, and other pages (Teacher Subjects, School Staffs, Reports, etc.) read
    // that same shared slot with a "skip fetch if already cached" guard, so leaving this in redux
    // let whichever role fetched last here silently leak into those pages.
    employeeList: [],
    // Starts true so the first render shows the table's own loading skeleton instead of the
    // "No teachers/workers found" empty state - that empty state should only ever reflect a
    // completed, genuinely-empty fetch, not the split second before fetchEmployees resolves.
    isEmployeesLoading: true,
    // Which employee rows have their day-wise breakdown open in the Weekly/Monthly summary
    // table - Monthly is always a single row (see isRowExpanded) so this only matters for Weekly.
    expandedEmployeeIds: [],
  };

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool?.schoolId) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchEmployees();
        this.fetchConfiguration();
        this.fetchAttendance();
      });
    }
  }

  fetchEmployees = async () => {
    // Filtered server-side by the BE's own profession param - no client-side designation-text
    // guessing. Teacher and Worker are separate mounted instances of this component (different
    // `key` per tab in StaffAttendanceHubPage), so each fetches only its own role's list.
    const employeeList =
      (await fetchSchoolEmployeesApi({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
        profession: this.props.roleFilter === 'teacher' ? 'TEACHING' : 'NON_TEACHING',
      })) || [];
    this.setState({ employeeList, isEmployeesLoading: false });
    // Default to the 0th employee the first time the list arrives, if nothing was already
    // selected/persisted - only relevant for Monthly, which requires a selection.
    if (!this.state.selectedEmployeeId && employeeList.length) {
      this.changeSelectedEmployee(employeeList[0].employeeId);
    }
  };

  fetchConfiguration = async () => {
    // fetchAttendanceConfigService is written as a thunk (`data => async () => {...}`) even
    // though it ignores dispatch/getState - has to be invoked as fetchAttendanceConfigService(data)()
    // rather than awaited directly, or `configuration` ends up being that inner function itself.
    const configuration = await fetchAttendanceConfigService({
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
    })();
    this.setState({ attendanceConfiguration: configuration });
  };

  fetchAttendance = async () => {
    const { viewMode, schoolId, selectedDate, selectedEmployeeId, weekRange, monthRange } = this.state;

    if (viewMode === 'daily') {
      // Daily still reads the raw per-day records - the edit modal needs the
      // employeeDailyAttendanceId to save against, which the report DTOs don't carry.
      this.setState({ isLoading: true });
      await this.props.fetchAttendanceRange({
        schoolId,
        fromDate: moment(selectedDate).format('YYYY-MM-DD'),
        toDate: moment(selectedDate).format('YYYY-MM-DD'),
        token: this.props.loggedUserToken,
      });
      this.setState({ isLoading: false });
      return;
    }

    // Weekly/Monthly both ride the report endpoint's DATE_RANGE type regardless of span length -
    // Weekly stays whole-school (employeeId omitted, like Daily); Monthly is scoped to one
    // selected employee - nothing to fetch yet if that hasn't been picked.
    let fromDate;
    let toDate;
    let employeeId;
    if (viewMode === 'weekly') {
      fromDate = weekRange.fromDate;
      toDate = weekRange.toDate;
    } else {
      if (!selectedEmployeeId) return;
      fromDate = moment(monthRange.fromMonth, 'YYYY-MM').startOf('month').format('YYYY-MM-DD');
      toDate = moment(monthRange.toMonth, 'YYYY-MM').endOf('month').format('YYYY-MM-DD');
      employeeId = selectedEmployeeId;
    }

    this.setState({ isLoading: true });
    try {
      const report = await fetchAttendanceReportService({
        schoolId,
        reportType: 'DATE_RANGE',
        token: this.props.loggedUserToken,
        fromDate,
        toDate,
        ...(employeeId ? { employeeId } : {}),
      });
      this.setState({ reportData: report });
    } catch (err) {
      this.setState({ reportData: null });
    }
    this.setState({ isLoading: false });
  };

  // The report endpoint returns data to render in-page (see fetchAttendance), not a PDF, so there's
  // nothing to "generate" - picking a period switches straight to it, the same way the Period
  // wise/Day wise toggle on the Attendance tab applies its choice immediately.
  changeViewMode = viewMode => {
    if (viewMode !== this.state.viewMode) {
      setLocalStore(viewModeStoreKey(this.props.roleFilter), viewMode);
      this.setState({ viewMode }, this.fetchAttendance);
    }
  };

  changeDate = date => this.setState({ selectedDate: date }, this.fetchAttendance);

  changeSelectedEmployee = employeeId => {
    setLocalStore(employeeStoreKey(this.props.roleFilter), employeeId);
    this.setState({ selectedEmployeeId: employeeId }, this.fetchAttendance);
  };

  // Constrained at the picker itself (min/max on the "To" field, see render) rather than
  // validated after the fact - picking a "From" that makes the current "To" fall outside the
  // 1-3 week window clamps "To" back into range instead of showing an error.
  changeWeekRange = (field, value) => {
    let { fromDate, toDate } = this.state.weekRange;
    if (field === 'fromDate') {
      fromDate = value;
      const span = weekSpanDays(fromDate, toDate);
      if (span < MIN_WEEK_SPAN_DAYS) toDate = minWeekToDate(fromDate);
      else if (span > MAX_WEEK_SPAN_DAYS) toDate = maxWeekToDate(fromDate);
    } else {
      toDate = value;
      if (moment(toDate).isBefore(minWeekToDate(fromDate))) toDate = minWeekToDate(fromDate);
      else if (moment(toDate).isAfter(maxWeekToDate(fromDate))) toDate = maxWeekToDate(fromDate);
    }
    this.setState({ weekRange: { fromDate, toDate } }, this.fetchAttendance);
  };

  // Same clamp-at-the-picker approach as Weekly, capped at MAX_MONTH_SPAN (3 years) instead of
  // requiring a minimum - a single month is a valid pick now that Annual has folded in here.
  changeMonthRange = (field, value) => {
    let { fromMonth, toMonth } = this.state.monthRange;
    if (field === 'fromMonth') {
      fromMonth = value;
      if (moment(toMonth, 'YYYY-MM').isBefore(moment(fromMonth, 'YYYY-MM'))) toMonth = fromMonth;
      else if (monthSpanCount(fromMonth, toMonth) > MAX_MONTH_SPAN) toMonth = maxMonthToMonth(fromMonth);
    } else {
      toMonth = value;
      if (moment(toMonth, 'YYYY-MM').isBefore(moment(fromMonth, 'YYYY-MM'))) toMonth = fromMonth;
      else if (monthSpanCount(fromMonth, toMonth) > MAX_MONTH_SPAN) toMonth = maxMonthToMonth(fromMonth);
    }
    this.setState({ monthRange: { fromMonth, toMonth } }, this.fetchAttendance);
  };

  // Already filtered server-side (see fetchEmployees) - nothing left to filter here.
  getStaffList = () => this.state.employeeList || [];

  openEditModal = employee => this.setState({ editModalOpen: true, editEmployee: employee });

  closeEditModal = () => this.setState({ editModalOpen: false, editEmployee: null });

  onSessionsSaved = () => {
    this.closeEditModal();
    this.fetchAttendance();
  };

  findDailyAttendance = employeeId => {
    const dateStr = moment(this.state.selectedDate).format('YYYY-MM-DD');
    return this.props.attendanceRange.find(a => a.employeeId === employeeId && a.attendanceDate === dateStr);
  };

  isLate = firstInTime => {
    const scheduledInTime = this.state.attendanceConfiguration?.inTime;
    if (!scheduledInTime || !firstInTime) return false;
    return moment(firstInTime, 'HH:mm:ss').isAfter(moment(scheduledInTime, 'HH:mm:ss'));
  };

  // Same three cards the mobile app shows above its day list (Present / Absent / Late), worked out the same way from the
  // rows below: present = has at least one session that day, absent = everyone else, late = first check-in after the
  // configured in-time. Only for Daily; Weekly/Monthly already carry these as columns.
  renderDailyStats = () => {
    const loading = this.state.isLoading || this.state.isEmployeesLoading;
    const staffList = this.getStaffList();
    let present = 0;
    let late = 0;
    staffList.forEach(employee => {
      const firstIn = this.findDailyAttendance(employee.employeeId)?.sessions?.[0]?.inTime;
      if (firstIn) {
        present += 1;
        if (this.isLate(firstIn)) late += 1;
      }
    });
    return (
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 14 }}>
        <StatTile label="Present" value={present} tone="good" loading={loading} />
        <StatTile label="Absent" value={staffList.length - present} tone="bad" loading={loading} />
        <StatTile label="Late" value={late} tone="warn" loading={loading} />
      </div>
    );
  };

  renderDailyTable = () => {
    const staffList = this.getStaffList();
    // Editing a check-in/out only makes sense for a day that's already happened - a future date
    // has nothing to correct yet.
    const isFutureDate = moment(this.state.selectedDate).isAfter(moment(), 'day');
    const rows = staffList.map(employee => {
      const dailyAttendance = this.findDailyAttendance(employee.employeeId);
      const sessions = dailyAttendance?.sessions || [];
      const firstIn = sessions[0]?.inTime;
      return {
        employeeId: employee.employeeId,
        name: employee.name,
        designation: employee.designation,
        sessions: sessions.length ? (
          <span>
            {sessions.map((s, i) => (
              <span key={i} style={{ display: 'block' }}>
                {formatTime(s.inTime)} - {s.outTime ? formatTime(s.outTime) : 'In progress'}
              </span>
            ))}
          </span>
        ) : (
          <span style={{ color: colors.grey3 }}>No record</span>
        ),
        status: !sessions.length ? (
          <span style={{ color: colors.grey3, fontWeight: 'bold', fontSize: 12 }}>ABSENT</span>
        ) : this.isLate(firstIn) ? (
          <span style={{ color: '#e53935', fontWeight: 'bold', fontSize: 12 }}>LATE</span>
        ) : (
          <span style={{ color: colors.secondary2, fontWeight: 'bold', fontSize: 12 }}>ON TIME</span>
        ),
        edit: isFutureDate ? (
          <CommonTooltip content="Can't edit a date that hasn't happened yet">
            <span>
              <IconButton size="small" disabled>
                <EditIcon fontSize="small" style={{ color: colors.grey3 }} />
              </IconButton>
            </span>
          </CommonTooltip>
        ) : (
          <IconButton size="small" onClick={() => this.openEditModal(employee)}>
            <EditIcon fontSize="small" style={{ color: colors.accent }} />
          </IconButton>
        ),
      };
    });

    return (
      <MuiTable
        tableHeaders={['Name', 'Designation', 'Sessions', 'Status', 'Edit']}
        tableBodyData={{ content: rows }}
        bodyColumns={['name', 'designation', 'sessions', 'status', 'edit']}
        idName="employeeId"
        hidePagination={true}
        isLoading={this.state.isLoading || this.state.isEmployeesLoading}
      />
    );
  };

  // Late isn't tracked at the summary level by the report endpoint (only PRESENT/ABSENT/
  // INCOMPLETE counts) - each summary carries its own dailyBreakdown though, which has the same
  // per-day sessions the daily view uses, so late days can still be derived from that.
  lateDaysFromBreakdown = dailyBreakdown =>
    (dailyBreakdown || []).filter(day => day.sessions?.length && this.isLate(day.sessions[0]?.inTime)).length;

  // Monthly is scoped to the one selected employee (see the employee picker in render) - Weekly
  // stays whole-school like Daily.
  getSummaryStaffList = () => {
    const { viewMode, selectedEmployeeId } = this.state;
    const staffList = this.getStaffList();
    if (viewMode === 'monthly') {
      return staffList.filter(emp => emp.employeeId === selectedEmployeeId);
    }
    return staffList;
  };

  buildSummaryRows = () => {
    const staffList = this.getSummaryStaffList();
    // Weekly/Monthly both read the same reportData.summaryReport shape, both riding the report
    // endpoint's DATE_RANGE type (see fetchAttendance).
    const summaryByEmployee = {};
    (this.state.reportData?.summaryReport || []).forEach(s => {
      summaryByEmployee[s.employeeId] = s;
    });
    return staffList.map(employee => {
      const summary = summaryByEmployee[employee.employeeId];
      return {
        employeeId: employee.employeeId,
        name: employee.name,
        designation: employee.designation,
        presentDays: summary ? `${summary.presentDays} / ${summary.totalDaysInRange}` : '0 / 0',
        absentDays: summary?.absentDays ?? 0,
        incompleteDays: summary?.incompleteDays ?? 0,
        lateDays: summary ? this.lateDaysFromBreakdown(summary.dailyBreakdown) : 0,
        totalWorkingHours: summary?.totalWorkingHours || '00:00',
        // Only used to render the expandable day-wise rows below - not part of the CSV export
        // columns (see exportCsv, which maps its own explicit field list).
        dailyBreakdown: summary?.dailyBreakdown || [],
      };
    });
  };

  // Monthly is already scoped to a single employee (see getSummaryStaffList), so there's nothing
  // to toggle - the one row's day-wise breakdown is always shown. Weekly can list a whole
  // school's worth of employees, so those rows start collapsed and open individually.
  isRowExpanded = employeeId =>
    this.getSummaryStaffList().length === 1 || this.state.expandedEmployeeIds.includes(employeeId);

  toggleEmployeeExpanded = employeeId => {
    this.setState(prev => ({
      expandedEmployeeIds: prev.expandedEmployeeIds.includes(employeeId)
        ? prev.expandedEmployeeIds.filter(id => id !== employeeId)
        : [...prev.expandedEmployeeIds, employeeId],
    }));
  };

  // Day-level status badge for the breakdown table - same LATE/ON TIME distinction the Daily
  // table already makes (via isLate), layered on top of the server-computed ABSENT/INCOMPLETE
  // dayStatus which takes priority since there's no "in time" to compare on those days.
  dayStatusBadge = (dayStatus, firstInTime) => {
    if (dayStatus === 'ABSENT') {
      return <span style={{ color: colors.grey3, fontWeight: 'bold', fontSize: 12 }}>ABSENT</span>;
    }
    if (dayStatus === 'INCOMPLETE') {
      return <span style={{ color: '#e53935', fontWeight: 'bold', fontSize: 12 }}>INCOMPLETE</span>;
    }
    if (this.isLate(firstInTime)) {
      return <span style={{ color: '#e53935', fontWeight: 'bold', fontSize: 12 }}>LATE</span>;
    }
    return <span style={{ color: colors.secondary2, fontWeight: 'bold', fontSize: 12 }}>ON TIME</span>;
  };

  // Mirrors the mobile teacher "My Attendance" list's own In/Out layout (date, in, out, status)
  // plus the total worked duration the server already computes, so the same period reads the
  // same way whether a teacher looks at their own history or an admin looks at the summary.
  renderDayBreakdown = dailyBreakdown => {
    const days = [...(dailyBreakdown || [])].sort((a, b) => moment(a.attendanceDate).diff(moment(b.attendanceDate)));
    if (!days.length) {
      return (
        <div style={{ padding: '10px 16px', color: colors.grey3, fontSize: 13 }}>
          No attendance records in this period.
        </div>
      );
    }
    return (
      <Table size="small">
        <TableHead>
          <TableRow>
            {['Date', 'In', 'Out', 'Duration', 'Status'].map(h => (
              <TableCell key={h} style={{ fontWeight: 'bold', fontSize: 11, color: colors.grey3 }}>
                {h}
              </TableCell>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {days.map(day => {
            // A day with only one session already shows everything it has in the day row
            // itself - no point collapsing a single line behind another toggle. Multiple
            // sessions (e.g. a lunch-break out/in) get their own sub-rows right below, always
            // visible: the employee-level collapse above is what hides real bulk (a whole
            // month), a day's own session count never gets large enough to need hiding too.
            const sessions = day.sessions || [];
            return (
              <React.Fragment key={day.attendanceDate}>
                <TableRow>
                  <TableCell style={{ fontSize: 13 }}>
                    {moment(day.attendanceDate).format('ddd, MMM D, YYYY')}
                  </TableCell>
                  <TableCell style={{ fontSize: 13 }}>{formatTime(day.firstInTime)}</TableCell>
                  <TableCell style={{ fontSize: 13 }}>
                    {day.firstInTime && !day.lastOutTime ? (
                      <span style={{ color: '#e53935', fontWeight: 'bold' }}>IN PROGRESS</span>
                    ) : (
                      formatTime(day.lastOutTime)
                    )}
                  </TableCell>
                  <TableCell style={{ fontSize: 13 }}>{day.totalWorkingDuration || '--'}</TableCell>
                  <TableCell>{this.dayStatusBadge(day.dayStatus, day.firstInTime)}</TableCell>
                </TableRow>
                {sessions.length > 1 &&
                  sessions.map((session, i) => (
                    <TableRow key={`${day.attendanceDate}-${i}`} style={{ backgroundColor: 'rgba(0,0,0,.02)' }}>
                      <TableCell style={{ fontSize: 12, color: colors.grey3, paddingLeft: 28 }}>
                        Session {i + 1}
                      </TableCell>
                      <TableCell style={{ fontSize: 12, color: colors.grey3 }}>{formatTime(session.inTime)}</TableCell>
                      <TableCell style={{ fontSize: 12, color: colors.grey3 }}>
                        {session.inTime && !session.outTime ? (
                          <span style={{ color: '#e53935', fontWeight: 'bold' }}>IN PROGRESS</span>
                        ) : (
                          formatTime(session.outTime)
                        )}
                      </TableCell>
                      <TableCell style={{ fontSize: 12, color: colors.grey3 }}>{session.duration || '--'}</TableCell>
                      <TableCell />
                    </TableRow>
                  ))}
              </React.Fragment>
            );
          })}
        </TableBody>
      </Table>
    );
  };

  renderSummaryTable = () => {
    const rows = this.buildSummaryRows();
    const loading = this.state.isLoading || this.state.isEmployeesLoading;
    const headers = [
      '',
      'Name',
      'Designation',
      'Present Days',
      'Absent Days',
      'Incomplete',
      'Late Days',
      'Total Hours',
    ];

    return (
      <TableContainer component={Paper} style={{ padding: 5 }}>
        <Table size="small" aria-label="attendance summary with day-wise breakdown">
          <TableHead>
            <TableRow>
              {headers.map((h, i) => (
                <TableCell key={i} style={{ paddingTop: 10, paddingBottom: 12 }}>
                  {h && (
                    <Typography variant="h6" style={{ fontWeight: 'bold' }}>
                      {h}
                    </Typography>
                  )}
                </TableCell>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              new Array(6).fill(0).map((el, i) => (
                <TableRow key={i}>
                  {headers.map((h, j) => (
                    <TableCell key={j}>
                      <Skeleton animation="wave" variant="text" />
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : rows.length ? (
              rows.map(row => {
                const expanded = this.isRowExpanded(row.employeeId);
                const canToggle = this.getSummaryStaffList().length > 1;
                return (
                  <React.Fragment key={row.employeeId}>
                    <TableRow style={{ borderBottom: expanded ? 'none' : '0.5px solid lightgrey' }}>
                      <TableCell style={{ width: 40, paddingTop: 15, paddingBottom: 15 }}>
                        {canToggle && (
                          <IconButton size="small" onClick={() => this.toggleEmployeeExpanded(row.employeeId)}>
                            {expanded ? (
                              <KeyboardArrowUpIcon fontSize="small" />
                            ) : (
                              <KeyboardArrowDownIcon fontSize="small" />
                            )}
                          </IconButton>
                        )}
                      </TableCell>
                      <TableCell style={{ paddingTop: 15, paddingBottom: 15 }}>{row.name}</TableCell>
                      <TableCell style={{ paddingTop: 15, paddingBottom: 15 }}>{row.designation}</TableCell>
                      <TableCell style={{ paddingTop: 15, paddingBottom: 15 }}>{row.presentDays}</TableCell>
                      <TableCell style={{ paddingTop: 15, paddingBottom: 15 }}>{row.absentDays}</TableCell>
                      <TableCell style={{ paddingTop: 15, paddingBottom: 15 }}>{row.incompleteDays}</TableCell>
                      <TableCell style={{ paddingTop: 15, paddingBottom: 15 }}>{row.lateDays}</TableCell>
                      <TableCell style={{ paddingTop: 15, paddingBottom: 15 }}>{row.totalWorkingHours}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell style={{ padding: 0, borderBottom: '0.5px solid lightgrey' }} colSpan={headers.length}>
                        <Collapse in={expanded} timeout="auto" unmountOnExit>
                          <div style={{ backgroundColor: 'rgba(0,0,0,.02)', padding: '8px 0' }}>
                            {this.renderDayBreakdown(row.dailyBreakdown)}
                          </div>
                        </Collapse>
                      </TableCell>
                    </TableRow>
                  </React.Fragment>
                );
              })
            ) : (
              <TableRow>
                <TableCell
                  style={{ textAlign: 'center', fontWeight: 'bold', paddingTop: 20, paddingBottom: 15 }}
                  colSpan={headers.length}>
                  No Data Found.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
    );
  };

  exportCsv = () => {
    const rows = this.buildSummaryRows();
    const header = ['Name', 'Designation', 'Present Days', 'Absent Days', 'Incomplete', 'Late Days', 'Total Hours'];
    const body = rows.map(r => [
      r.name,
      r.designation,
      r.presentDays,
      r.absentDays,
      r.incompleteDays,
      r.lateDays,
      r.totalWorkingHours,
    ]);
    downloadCsv(`${this.props.roleFilter}-attendance-${this.state.viewMode}-${moment().format('YYYY-MM-DD')}.csv`, [
      header,
      ...body,
    ]);
  };

  renderEmptyStaffNotice = () => {
    const { roleFilter } = this.props;
    return (
      !this.state.isEmployeesLoading &&
      this.getStaffList().length === 0 && (
        <EmptyState
          icon={<PeopleOutlineIcon style={{ color: colors.accent, fontSize: 30 }} />}
          title={roleFilter === 'teacher' ? 'No teachers found' : 'No workers found'}
          subtitle={
            roleFilter === 'teacher'
              ? 'No employees are marked as Teaching yet. Add a teacher or set the Profession field on School Staffs.'
              : "No non-teaching staff found yet. Set an employee's Profession to Non-teaching on the Teachers " +
                'page to see them here.'
          }
        />
      )
    );
  };

  renderEmployeePicker = () => {
    const empArr = formEmpSelectList(this.getStaffList());
    return (
      <div style={{ minWidth: 220, flex: 1, maxWidth: 320 }}>
        <CustomSelect
          name="selectedEmployeeId"
          noLabel={true}
          value={this.state.selectedEmployeeId}
          onChange={(name, value) => this.changeSelectedEmployee(value)}
          options={empArr}
          applyLabelStyle={true}
        />
      </div>
    );
  };

  render() {
    const { viewMode, selectedDate, editModalOpen, editEmployee, weekRange, monthRange } = this.state;
    const hasStaff = this.getStaffList().length > 0;
    const isSingleEmployeeView = viewMode === 'monthly';
    const canExport = hasStaff && viewMode !== 'daily' && (!isSingleEmployeeView || !!this.state.selectedEmployeeId);

    return (
      <div>
        <Row className="mb-2" style={{ alignItems: 'center' }}>
          <Col sm={12} md={7} lg={8}>
            <div
              style={{
                display: 'inline-flex',
                borderRadius: 8,
                border: `1.5px solid ${colors.accent}`,
                overflow: 'hidden',
              }}>
              {REPORT_VIEWS.map((view, index) => {
                const isActive = viewMode === view.key;
                return (
                  <button
                    key={view.key}
                    type="button"
                    onClick={() => this.changeViewMode(view.key)}
                    style={{
                      border: 'none',
                      borderLeft: index > 0 ? `1px solid ${colors.accent}` : 'none',
                      outline: 'none',
                      cursor: 'pointer',
                      padding: '8px 16px',
                      fontSize: 13,
                      fontWeight: 'bold',
                      backgroundColor: isActive ? colors.accent : '#FFFFFF',
                      color: isActive ? '#FFFFFF' : colors.accent,
                      transition: 'background-color 0.15s ease',
                    }}>
                    {view.label}
                  </button>
                );
              })}
            </div>
          </Col>
          <Col sm={12} md={5} lg={4} style={{ textAlign: 'right' }}>
            {canExport && (
              <CustomButton
                className="mr-2"
                variant="outlined"
                size="small"
                onClick={this.exportCsv}
                name="Export CSV"
              />
            )}
          </Col>
        </Row>
        <Row className="mb-2" style={{ alignItems: 'center' }}>
          <Col sm={12} style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
            {viewMode === 'daily' && (
              <>
                <span style={{ fontSize: 12, color: colors.grey3 }}>Date</span>
                <input
                  type="date"
                  className="form-control"
                  style={{ display: 'inline-block', width: 'auto' }}
                  value={moment(selectedDate).format('YYYY-MM-DD')}
                  onChange={e => this.changeDate(moment(e.target.value, 'YYYY-MM-DD').toDate())}
                />
                {!!this.state.attendanceConfiguration?.inTime && (
                  <span style={{ fontSize: 12, color: colors.grey3 }}>
                    &middot; Marked LATE after{' '}
                    {moment(this.state.attendanceConfiguration.inTime, 'HH:mm:ss').format('hh:mm A')}
                  </span>
                )}
              </>
            )}
            {viewMode === 'weekly' && (
              <>
                <span style={{ fontSize: 12, color: colors.grey3 }}>From</span>
                <input
                  type="date"
                  className="form-control"
                  style={{ display: 'inline-block', width: 'auto' }}
                  value={weekRange.fromDate}
                  onChange={e => this.changeWeekRange('fromDate', e.target.value)}
                />
                <span style={{ fontSize: 12, color: colors.grey3 }}>To</span>
                <input
                  type="date"
                  className="form-control"
                  style={{ display: 'inline-block', width: 'auto' }}
                  value={weekRange.toDate}
                  min={minWeekToDate(weekRange.fromDate)}
                  max={maxWeekToDate(weekRange.fromDate)}
                  onChange={e => this.changeWeekRange('toDate', e.target.value)}
                />
                <span style={{ fontSize: 12, color: colors.grey3 }}>(1-3 weeks)</span>
              </>
            )}
            {viewMode === 'monthly' && (
              <>
                {hasStaff && this.renderEmployeePicker()}
                <span style={{ fontSize: 12, color: colors.grey3 }}>From</span>
                <input
                  type="month"
                  className="form-control"
                  style={{ display: 'inline-block', width: 'auto' }}
                  value={monthRange.fromMonth}
                  onChange={e => this.changeMonthRange('fromMonth', e.target.value)}
                />
                <span style={{ fontSize: 12, color: colors.grey3 }}>To</span>
                <input
                  type="month"
                  className="form-control"
                  style={{ display: 'inline-block', width: 'auto' }}
                  value={monthRange.toMonth}
                  min={monthRange.fromMonth}
                  max={maxMonthToMonth(monthRange.fromMonth)}
                  onChange={e => this.changeMonthRange('toMonth', e.target.value)}
                />
                <span style={{ fontSize: 12, color: colors.grey3 }}>(up to 3 years)</span>
              </>
            )}
          </Col>
        </Row>
        {viewMode !== 'daily' && (
          <div style={{ fontSize: 12, color: colors.grey3, marginBottom: 10 }}>
            Read-only summary for this period &mdash; switch to Daily to correct a specific check-in/check-out.
          </div>
        )}
        {this.renderEmptyStaffNotice()}
        {(hasStaff || this.state.isEmployeesLoading) &&
          (viewMode === 'daily' ? (
            <>
              {this.renderDailyStats()}
              {this.renderDailyTable()}
            </>
          ) : isSingleEmployeeView && !this.state.selectedEmployeeId && !this.state.isEmployeesLoading ? null : (
            this.renderSummaryTable()
          ))}
        <AttendanceEditModal
          isOpen={editModalOpen}
          employee={editEmployee}
          selectedDate={selectedDate}
          schoolId={this.state.schoolId}
          token={this.props.loggedUserToken}
          dailyAttendance={editEmployee ? this.findDailyAttendance(editEmployee.employeeId) : null}
          onClose={this.closeEditModal}
          onSaved={this.onSessionsSaved}
        />
      </div>
    );
  }
}

const mapStateToProps = state => ({
  loggedUserToken: state.auth.loggedUserToken,
  attendanceRange: state.attendance.attendanceRange || [],
});

const mapDispatchToProps = dispatch => ({
  fetchAttendanceRange: data => dispatch(fetchAttendanceRangeService(data)),
});

export default connect(mapStateToProps, mapDispatchToProps)(StaffAttendanceRolePanel);
