import React from 'react';
import moment from 'moment';
import colors from '../../../../config/colors';

const HOURS = Array.from({ length: 12 }, (_, i) => i + 1);
const MINUTES = Array.from({ length: 60 }, (_, i) => i);

// Native <input type="time"> renders differently per browser (24h vs 12h, seconds sub-field
// leaking through when the bound value carries them - see toHHmm in AttendanceEditModal) and
// isn't obviously a time picker to every admin. Three explicit controls - hour, minute, AM/PM -
// read the same way regardless of browser/OS.
const SimpleTimePicker = ({ value, onChange }) => {
  const parsed = value ? moment(value, 'HH:mm') : null;
  const hour = parsed ? Number(parsed.format('h')) : '';
  const minute = parsed ? parsed.minutes() : '';
  const meridiem = parsed ? parsed.format('A') : 'AM';

  const emit = (nextHour, nextMinute, nextMeridiem) => {
    if (nextHour === '' || nextMinute === '') return;
    onChange(moment(`${nextHour}:${nextMinute} ${nextMeridiem}`, 'h:m A').format('HH:mm'));
  };

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
      <select
        className="form-control"
        style={{ width: 62, padding: '4px 6px' }}
        value={hour}
        onChange={e => emit(Number(e.target.value), minute === '' ? 0 : minute, meridiem)}>
        <option value="" disabled>
          HH
        </option>
        {HOURS.map(h => (
          <option key={h} value={h}>
            {h}
          </option>
        ))}
      </select>
      <span>:</span>
      <select
        className="form-control"
        style={{ width: 66, padding: '4px 6px' }}
        value={minute}
        onChange={e => emit(hour === '' ? 12 : hour, Number(e.target.value), meridiem)}>
        <option value="" disabled>
          MM
        </option>
        {MINUTES.map(m => (
          <option key={m} value={m}>
            {String(m).padStart(2, '0')}
          </option>
        ))}
      </select>
      <div
        style={{ display: 'inline-flex', borderRadius: 6, overflow: 'hidden', border: `1px solid ${colors.accent}` }}>
        {['AM', 'PM'].map(ap => (
          <button
            key={ap}
            type="button"
            onClick={() => emit(hour === '' ? 12 : hour, minute === '' ? 0 : minute, ap)}
            style={{
              border: 'none',
              padding: '5px 8px',
              fontSize: 12,
              fontWeight: 'bold',
              cursor: 'pointer',
              backgroundColor: meridiem === ap ? colors.accent : '#FFFFFF',
              color: meridiem === ap ? '#FFFFFF' : colors.accent,
            }}>
            {ap}
          </button>
        ))}
      </div>
    </div>
  );
};

export default SimpleTimePicker;
