import moment from 'moment';

// A leave date reaches the page in more than one shape depending on the backend build: 'YYYY-MM-DD', an ISO date time,
// epoch milliseconds (a number or a numeric string) or a [year, month, day] array. Every leave screen reads it through here
// so none prints a raw number or "Invalid date".
export const toLeaveDate = value => {
  if (value === undefined || value === null || value === '') {
    return '';
  }
  if (value instanceof Date || moment.isMoment(value)) {
    return moment(value).format('YYYY-MM-DD');
  }
  if (Array.isArray(value)) {
    const [year, month, day] = value;
    return moment({ year, month: month - 1, day }).format('YYYY-MM-DD');
  }
  if (typeof value === 'number' || /^\d{9,}$/.test(`${value}`.trim())) {
    return moment(Number(value)).format('YYYY-MM-DD');
  }
  const text = `${value}`.trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(text)) {
    return text.slice(0, 10);
  }
  const parsed = moment(new Date(text));
  return parsed.isValid() ? parsed.format('YYYY-MM-DD') : '';
};

export const formatLeaveDate = value => {
  const date = toLeaveDate(value);
  return date ? moment(date).format('LL') : '--';
};

export const leaveDayCount = (start, end) => {
  const startDate = toLeaveDate(start);
  const endDate = toLeaveDate(end) || startDate;
  return startDate ? moment(endDate).diff(moment(startDate), 'days') + 1 : 0;
};
