import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import moment from 'moment';
import DeleteIcon from '@material-ui/icons/Delete';
import AddIcon from '@material-ui/icons/Add';
import ClearIcon from '@material-ui/icons/Clear';
import IconButton from '@material-ui/core/IconButton';
import CustomButton from '../../../../components/CustomButton';
import { formResMessage } from '../../../../utils/commonFunc';
import colors from '../../../../config/colors';
import SimpleTimePicker from './SimpleTimePicker.jsx';
import {
  createDailyAttendanceApi,
  addAttendanceSessionApi,
  updateAttendanceSessionApi,
  deleteAttendanceSessionApi,
} from '../../../../actions/admin/attendance';

// Admin has no location to verify (unlike the teacher's own mobile check-in/out), so this only
// ever talks to the plain session CRUD endpoints - PUT /session already has no server-side
// geofence check (confirmed by reading EmployeeDailyAttendanceServiceImpl), so no separate
// "admin override" endpoint is needed.
const emptySession = () => ({
  employeeAttendanceSessionId: null,
  inTime: moment().format('HH:mm'),
  outTime: null,
  isNew: true,
});

// The stored session carries real HH:mm:ss precision (e.g. "11:45:48") - feeding that straight
// into an <input type="time"> makes Chromium/Safari reveal a seconds sub-field even though the
// input has no step="1", since the value itself (not just step) decides whether seconds show.
// Truncating to HH:mm here is what actually removes seconds from the picker.
const toHHmm = time => (time ? moment(time, 'HH:mm:ss').format('HH:mm') : time);

const toSessionRow = session => ({
  employeeAttendanceSessionId: session.employeeAttendanceSessionId,
  inTime: toHHmm(session.inTime),
  outTime: toHHmm(session.outTime) || null,
  isNew: false,
});

class AttendanceEditModal extends React.Component {
  state = {
    sessions: [],
    saving: false,
    error: '',
  };

  componentDidUpdate(prevProps) {
    const { isOpen, dailyAttendance } = this.props;
    if (isOpen && !prevProps.isOpen) {
      this.setState({
        sessions: dailyAttendance?.sessions?.length ? dailyAttendance.sessions.map(toSessionRow) : [],
        error: '',
      });
    }
  }

  addSessionRow = () => this.setState({ sessions: [...this.state.sessions, emptySession()] });

  updateSessionField = (index, field, value) => {
    const sessions = [...this.state.sessions];
    sessions[index] = { ...sessions[index], [field]: value };
    this.setState({ sessions });
  };

  removeSessionRow = async index => {
    const session = this.state.sessions[index];
    if (!session.isNew) {
      try {
        await deleteAttendanceSessionApi({
          employeeAttendanceSessionId: session.employeeAttendanceSessionId,
          token: this.props.token,
        });
      } catch (err) {
        this.setState({ error: formResMessage(err) });
        return;
      }
    }
    const sessions = this.state.sessions.filter((_, i) => i !== index);
    this.setState({ sessions });
  };

  handleSave = async () => {
    const { employee, schoolId, selectedDate, dailyAttendance, token } = this.props;
    const { sessions } = this.state;

    const invalid = sessions.find(s => !s.inTime || (s.outTime && s.outTime <= s.inTime));
    if (invalid) {
      this.setState({ error: 'Each session needs an in-time, and out-time (if set) must be after in-time.' });
      return;
    }

    this.setState({ saving: true, error: '' });
    try {
      let employeeDailyAttendanceId = dailyAttendance?.employeeDailyAttendanceId;
      if (!employeeDailyAttendanceId) {
        const res = await createDailyAttendanceApi({
          employeeId: employee.employeeId,
          schoolId,
          attendanceDate: moment(selectedDate).format('YYYY-MM-DD'),
          token,
        });
        employeeDailyAttendanceId = res.data.employeeDailyAttendanceId;
      }

      for (const session of sessions) {
        if (session.isNew) {
          // eslint-disable-next-line no-await-in-loop
          await addAttendanceSessionApi({
            employeeDailyAttendanceId,
            employeeId: employee.employeeId,
            schoolId,
            inTime: session.inTime,
            outTime: session.outTime,
            token,
          });
        } else {
          // eslint-disable-next-line no-await-in-loop
          await updateAttendanceSessionApi({
            employeeAttendanceSessionId: session.employeeAttendanceSessionId,
            employeeDailyAttendanceId,
            employeeId: employee.employeeId,
            schoolId,
            inTime: session.inTime,
            outTime: session.outTime,
            token,
          });
        }
      }

      this.setState({ saving: false });
      this.props.onSaved();
    } catch (err) {
      this.setState({ saving: false, error: formResMessage(err) });
    }
  };

  render() {
    const { isOpen, onClose, employee, selectedDate } = this.props;
    const { sessions, saving, error } = this.state;

    return (
      <Modal size="lg" isOpen={isOpen} toggle={onClose}>
        <ModalHeader toggle={onClose}>
          {employee?.name} &mdash; {moment(selectedDate).format('ddd, MMM D, YYYY')}
        </ModalHeader>
        <ModalBody>
          {error && <div className="mb-10 pad-12 alert alert-danger">{error}</div>}
          {sessions.length === 0 && (
            <div style={{ color: colors.grey3, marginBottom: 12, fontSize: 13 }}>
              No sessions recorded for this day yet.
            </div>
          )}
          {sessions.map((session, index) => (
            <div
              key={index}
              style={{ display: 'flex', alignItems: 'flex-end', gap: 20, flexWrap: 'wrap', marginBottom: 14 }}>
              <div>
                <label style={{ fontSize: 11, color: colors.grey3, marginBottom: 4, display: 'block' }}>In Time</label>
                <SimpleTimePicker
                  value={session.inTime}
                  onChange={value => this.updateSessionField(index, 'inTime', value)}
                />
              </div>
              <div>
                <label style={{ fontSize: 11, color: colors.grey3, marginBottom: 4, display: 'block' }}>Out Time</label>
                <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                  <SimpleTimePicker
                    value={session.outTime}
                    onChange={value => this.updateSessionField(index, 'outTime', value)}
                  />
                  {session.outTime && (
                    <IconButton size="small" onClick={() => this.updateSessionField(index, 'outTime', null)}>
                      <ClearIcon fontSize="small" style={{ color: colors.grey3 }} />
                    </IconButton>
                  )}
                </div>
              </div>
              <IconButton size="small" onClick={() => this.removeSessionRow(index)}>
                <DeleteIcon fontSize="small" style={{ color: colors.danger || '#e53935' }} />
              </IconButton>
            </div>
          ))}
          <CustomButton
            variant="outlined"
            size="small"
            onClick={this.addSessionRow}
            name={
              <>
                <AddIcon fontSize="small" style={{ verticalAlign: 'middle' }} /> Add Session
              </>
            }
          />
        </ModalBody>
        <ModalFooter>
          <CustomButton onClick={this.handleSave} name="Save" loading={saving} disabled={saving} showLoader={true} />
          <CustomButton className="ml-2" color="default" onClick={onClose} name="Cancel" />
        </ModalFooter>
      </Modal>
    );
  }
}

export default AttendanceEditModal;
