import React from 'react';
import { Paper, Tab, Tabs } from '@material-ui/core';
import SchoolIcon from '@material-ui/icons/School';
import WorkIcon from '@material-ui/icons/Work';
import AccessTimeIcon from '@material-ui/icons/AccessTime';
import EventBusyIcon from '@material-ui/icons/EventBusy';
import colors from '../../../config/colors';
import StaffAttendanceRolePanel from './StaffAttendanceRolePanel.jsx';
import StaffTimeAllowancePanel from './StaffTimeAllowancePanel.jsx';
import StaffLeavesPanel from './StaffLeavesPanel.jsx';
import { getLocalStore, setLocalStore } from '../../../utils/commonFunc';

const ACTIVE_TAB_STORE_KEY = 'staffAttendanceActiveTab';

// Four flat sibling tabs (not tabs-inside-a-tab) - Staff Time Allowance stands on its own
// alongside Teacher/Worker Attendance rather than nested under a sub-tab, per explicit direction
// to avoid a nested-tab structure. Used to be four tabs (a worker-only Salary Impact report
// separate from a Working Time Permission editor) - merged into one, since the allowance/
// deduction math and the per-person edit both belong together, and both now cover every staff
// member, not just workers.
const PAGE_TABS = [
  { key: 'teacher', label: 'Teacher Attendance', icon: <SchoolIcon /> },
  { key: 'worker', label: 'Worker Attendance', icon: <WorkIcon /> },
  { key: 'allowance', label: 'Staff Time Allowance', icon: <AccessTimeIcon /> },
  { key: 'leaves', label: 'Staff Leaves', icon: <EventBusyIcon /> },
];

class StaffAttendanceHubPage extends React.Component {
  state = { activeTab: getLocalStore(ACTIVE_TAB_STORE_KEY) || 'teacher' };

  changeTab = (event, tabIndex) => {
    const activeTab = PAGE_TABS[tabIndex].key;
    setLocalStore(ACTIVE_TAB_STORE_KEY, activeTab);
    this.setState({ activeTab });
  };

  renderActivePanel = () => {
    const { activeTab } = this.state;
    if (activeTab === 'teacher') return <StaffAttendanceRolePanel key="teacher" roleFilter="teacher" />;
    if (activeTab === 'worker') return <StaffAttendanceRolePanel key="worker" roleFilter="worker" />;
    if (activeTab === 'leaves') return <StaffLeavesPanel key="leaves" />;
    return <StaffTimeAllowancePanel key="allowance" />;
  };

  render() {
    const { activeTab } = this.state;
    const activeIndex = PAGE_TABS.findIndex(tab => tab.key === activeTab);

    return (
      <div className="content">
        <Paper square style={{ marginBottom: 16 }}>
          <Tabs
            value={activeIndex}
            onChange={this.changeTab}
            TabIndicatorProps={{ style: { display: 'none' } }}
            textColor="inherit"
            variant="standard">
            {PAGE_TABS.map((tab, index) => (
              <Tab
                key={tab.key}
                icon={tab.icon}
                label={tab.label}
                style={{
                  fontWeight: 'bold',
                  color: activeIndex === index ? colors.accent : '',
                  borderBottom: activeIndex === index ? `3px solid ${colors.accent}` : '',
                }}
              />
            ))}
          </Tabs>
        </Paper>
        {this.renderActivePanel()}
      </div>
    );
  }
}

export default StaffAttendanceHubPage;
