import React, { useCallback, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Input, Label, Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import ConfirmModal from 'views/admin/Common/ConfirmModal.jsx';
import MuiTable from 'views/admin/Common/MuiTable.jsx';
import CustomButton from 'components/CustomButton.jsx';
import { fetchLeaveTypesApi, saveLeaveTypeApi, deleteLeaveTypeApi } from 'actions/admin/employees';
import { showToast } from 'actions/admin/auth';
import { formResMessage, getGlobalSchoolUtils } from 'utils/commonFunc';
import { store } from '../../../index';

// Loss of pay has no balance to set, so it is not offered here.
const LEAVE_TYPES = [
  { value: 'CASUAL_LEAVE', label: 'Casual leave' },
  { value: 'SICK_LEAVE', label: 'Sick leave' },
  { value: 'EARNED_LEAVE', label: 'Earned leave' },
  { value: 'MATERNITY_LEAVE', label: 'Maternity leave' },
  { value: 'PATERNITY_LEAVES', label: 'Paternity leave' },
  { value: 'BEREAVEMENT_LEAVE', label: 'Bereavement leave' },
];
const labelOf = value => LEAVE_TYPES.find(item => item.value === value)?.label || value;

// The leave types a teacher can apply for, and how many days a year each allows. Without any, a teacher cannot apply for leave
// in the app (it asks them to contact the admin). Add one per kind of leave the school gives: "Add leave type" opens a small
// form for it (only the kinds not added yet), and Edit on a row changes its days.
const LeaveTypesPanel = () => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const [types, setTypes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState(null); // the row being changed, or null for a new one
  const [leaveType, setLeaveType] = useState(LEAVE_TYPES[0].value);
  const [totalLeaves, setTotalLeaves] = useState('');
  const [saving, setSaving] = useState(false);
  const [toDelete, setToDelete] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      setTypes(await fetchLeaveTypesApi({ schoolId, token }));
    } catch (err) {
      store.dispatch(showToast(formResMessage(err), 'error'));
    }
    setLoading(false);
  }, [schoolId, token]);

  useEffect(() => {
    load();
  }, [load]);

  const addable = LEAVE_TYPES.filter(item => !types.some(added => added.leaveType === item.value));

  const closeForm = () => {
    setFormOpen(false);
    setEditing(null);
    setTotalLeaves('');
  };

  const openAdd = () => {
    setEditing(null);
    setLeaveType(addable[0]?.value || LEAVE_TYPES[0].value);
    setTotalLeaves('');
    setFormOpen(true);
  };

  const openEdit = item => {
    setEditing(item);
    setLeaveType(item.leaveType);
    setTotalLeaves(`${item.totalLeaves ?? ''}`);
    setFormOpen(true);
  };

  const save = async () => {
    const days = Number(totalLeaves);
    if (!days || days < 1) {
      store.dispatch(showToast('Enter how many days a year this leave gives', 'warning'));
      return;
    }
    if (!editing && types.some(item => item.leaveType === leaveType)) {
      store.dispatch(showToast(`${labelOf(leaveType)} is already added. Edit it instead.`, 'warning'));
      return;
    }
    setSaving(true);
    try {
      await saveLeaveTypeApi({ schoolId, token, leaveType, totalLeaves: days, leaveTypeId: editing?.leaveTypeId });
      store.dispatch(showToast(editing ? 'Leave type updated' : 'Leave type added', 'success'));
      closeForm();
      load();
    } catch (err) {
      store.dispatch(showToast(formResMessage(err), 'error'));
    }
    setSaving(false);
  };

  const remove = async () => {
    try {
      await deleteLeaveTypeApi({ token, leaveTypeId: toDelete.leaveTypeId });
      store.dispatch(showToast('Leave type removed', 'success'));
      load();
    } catch (err) {
      store.dispatch(showToast(formResMessage(err), 'error'));
    }
    setToDelete(null);
  };

  const rows = {
    content: types.map(item => ({
      ...item,
      leaveTypeText: labelOf(item.leaveType),
      actionItem: (
        <>
          <CustomButton size="small" variant="outlined" name="Edit" onClick={() => openEdit(item)} />
          <CustomButton
            className="ml-2"
            size="small"
            variant="outlined"
            name="Remove"
            onClick={() => setToDelete(item)}
          />
        </>
      ),
    })),
  };

  return (
    <>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          flexWrap: 'wrap',
          gap: 10,
          marginBottom: 12,
        }}>
        <span style={{ fontSize: 13, color: '#6b778a' }}>
          Teachers can apply only for the leave types listed here. Add one for each kind of leave your school gives.
        </span>
        <CustomButton name="+ Add leave type" onClick={openAdd} disabled={!loading && !addable.length} />
      </div>
      <MuiTable
        tableHeaders={['Leave type', 'Days a year', 'Action']}
        tableBodyData={rows}
        bodyColumns={['leaveTypeText', 'totalLeaves', 'actionItem']}
        isLoading={loading}
      />
      <Modal isOpen={formOpen} toggle={saving ? undefined : closeForm} centered>
        <ModalHeader toggle={saving ? undefined : closeForm}>
          <span style={{ whiteSpace: 'nowrap' }}>{editing ? 'EDIT LEAVE TYPE' : 'ADD LEAVE TYPE'}</span>
        </ModalHeader>
        <ModalBody>
          <Label className="mb-1">Leave type</Label>
          <Input type="select" value={leaveType} disabled={!!editing} onChange={e => setLeaveType(e.target.value)}>
            {(editing ? LEAVE_TYPES : addable).map(item => (
              <option key={item.value} value={item.value}>
                {item.label}
              </option>
            ))}
          </Input>
          <Label className="mb-1 mt-3">Days a year</Label>
          <Input
            type="number"
            min={1}
            placeholder="e.g. 12"
            value={totalLeaves}
            onChange={e => setTotalLeaves(e.target.value)}
          />
          <small className="text-muted">How many days of this leave one teacher can take in a year.</small>
        </ModalBody>
        <ModalFooter>
          <CustomButton name={editing ? 'Update' : 'Add'} onClick={save} loading={saving} disabled={saving} />
          <CustomButton className="ml-2" color="default" name="Cancel" onClick={closeForm} disabled={saving} />
        </ModalFooter>
      </Modal>
      <ConfirmModal
        confirmMessage={`Remove ${
          toDelete ? labelOf(toDelete.leaveType) : ''
        }? Teachers will no longer be able to apply for it.`}
        confirmModalOpen={!!toDelete}
        deleteConfirm={remove}
        deleteCancel={() => setToDelete(null)}
      />
    </>
  );
};

export default LeaveTypesPanel;
