import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import CustomButton from '../../../../components/CustomButton';
import colors from '../../../../config/colors';
import {
  saveEmployeePermissionConfigApi,
  deleteEmployeePermissionConfigApi,
} from '../../../../actions/admin/attendance';

const emptyRow = () => ({ employeePermissionConfigId: null, permissionCount: 0, permissionMinutes: 0 });

const rowFromConfig = config => ({
  employeePermissionConfigId: config?.employeePermissionConfigId || null,
  permissionCount: config?.permissionCount ?? 0,
  permissionMinutes: config?.permissionMinutes ?? 0,
});

// A controlled <input type="number"> doesn't reliably re-format what's on screen while it's
// still focused (browsers hold onto whatever was literally typed, like "01", even once the bound
// value is the number 1) - type="text" plus stripping everything but digits and any leading zero
// here, on every keystroke, is what actually keeps the box showing just "1".
const sanitizeToInt = raw => {
  const digitsOnly = String(raw).replace(/[^0-9]/g, '');
  const stripped = digitsOnly.replace(/^0+(?=\d)/, '');
  return stripped === '' ? 0 : Number(stripped);
};

// One employee per open - "permission" here is the school's late-arrival forgiveness allowance
// (N permissions/month, each forgiving M minutes late), consumed by the Working Time Permission
// panel's per-row Update button and the Worker Salary Impact tab's read-only deduction math.
// Edits exactly the employee it was opened for, not a whole table - a previous version of this
// modal edited every worker's row at once in one table, which read as confusing since it wasn't
// obvious which row's changes an "Update" click actually saved.
const PermissionConfigModal = ({ isOpen, onClose, employee, config, schoolId, token, onSaved }) => {
  const [row, setRow] = useState(emptyRow());
  const [saved, setSaved] = useState(emptyRow());
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!isOpen) return;
    const initial = rowFromConfig(config);
    setRow(initial);
    setSaved(initial);
    setError('');
  }, [isOpen, config]);

  const updateField = (field, value) => setRow(prev => ({ ...prev, [field]: sanitizeToInt(value) }));

  const dirty = row.permissionCount !== saved.permissionCount || row.permissionMinutes !== saved.permissionMinutes;

  const handleSave = async () => {
    setIsSaving(true);
    setError('');
    try {
      const res = await saveEmployeePermissionConfigApi({ ...row, employeeId: employee.employeeId, schoolId, token });
      const next = res?.data ? rowFromConfig(res.data) : row;
      setRow(next);
      setSaved(next);
      onSaved();
    } catch (err) {
      setError('Could not save this. Please try again.');
    }
    setIsSaving(false);
  };

  const handleDelete = async () => {
    if (!row.employeePermissionConfigId) return;
    setIsDeleting(true);
    setError('');
    try {
      await deleteEmployeePermissionConfigApi({ employeePermissionConfigId: row.employeePermissionConfigId, token });
      const empty = emptyRow();
      setRow(empty);
      setSaved(empty);
      onSaved();
    } catch (err) {
      setError('Could not remove this. Please try again.');
    }
    setIsDeleting(false);
  };

  return (
    <Modal isOpen={isOpen} toggle={onClose}>
      <ModalHeader toggle={onClose}>
        {employee?.name ? `${employee.name}'s Working Time Permission` : 'Working Time Permission'}
      </ModalHeader>
      <ModalBody>
        <div style={{ fontSize: 12, color: colors.grey3, marginBottom: 16 }}>
          How many late-arrival permissions this person gets per month, and how many minutes each permission forgives.
        </div>
        {error && <div className="mb-10 pad-12 alert alert-danger">{error}</div>}
        <div style={{ display: 'flex', gap: 16 }}>
          <div style={{ flex: 1 }}>
            <label>Permissions / month</label>
            <input
              type="text"
              inputMode="numeric"
              pattern="[0-9]*"
              className="form-control"
              value={row.permissionCount}
              onChange={e => updateField('permissionCount', e.target.value)}
            />
          </div>
          <div style={{ flex: 1 }}>
            <label>Minutes / permission</label>
            <input
              type="text"
              inputMode="numeric"
              pattern="[0-9]*"
              className="form-control"
              value={row.permissionMinutes}
              onChange={e => updateField('permissionMinutes', e.target.value)}
            />
          </div>
        </div>
      </ModalBody>
      <ModalFooter>
        {row.employeePermissionConfigId && (
          <CustomButton
            variant="outlined"
            color="default"
            style={{ borderColor: colors.danger || '#e53935', color: colors.danger || '#e53935' }}
            disabled={isDeleting}
            loading={isDeleting}
            onClick={handleDelete}
            name="Delete"
          />
        )}
        <CustomButton disabled={!dirty || isSaving} loading={isSaving} onClick={handleSave} name="Save" />
        <CustomButton color="default" onClick={onClose} name="Close" />
      </ModalFooter>
    </Modal>
  );
};

export default PermissionConfigModal;
