// Teacher/worker classification is now done server-side via the profession query param on
// GET /api/admin/get-school-employees/{schoolId} (see fetchSchoolEmployeesApi) - every consumer
// fetches its own already-filtered list instead of guessing from designation text client-side.

export const downloadCsv = (filename, rows) => {
  const csv = rows.map(row => row.map(cell => `"${String(cell ?? '').replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.setAttribute('download', filename);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};
