import React from 'react';
import { connect } from 'react-redux';
import moment from 'moment';
import { Row, Col } from 'reactstrap';
import { Paper, Tab, Tabs } from '@material-ui/core';
import { fetchSchoolEmployeesApi } from '../../../actions/admin/employees';
import { fetchAttendanceRangeService, fetchPermissionConfigsApi } from '../../../actions/admin/attendance';
import { fetchAttendanceConfigService } from '../../../actions/admin/config';
import { getGlobalSchoolUtils, getLocalStore, setLocalStore } from '../../../utils/commonFunc';
import MuiTable from '../Common/MuiTable.jsx';
import CustomButton from '../../../components/CustomButton.jsx';
import colors from '../../../config/colors';
import { downloadCsv } from './staffAttendanceUtils.js';
import EmptyState from '../Common/EmptyState.jsx';
import PeopleOutlineIcon from '@material-ui/icons/PeopleOutline';
import PermissionConfigModal from './components/PermissionConfigModal.jsx';

const ACTIVE_TAB_STORE_KEY = 'staffTimeAllowanceActiveTab';

const ROLE_TABS = [
  { key: 'teacher', label: 'Teachers', profession: 'TEACHING' },
  { key: 'worker', label: 'Workers', profession: 'NON_TEACHING' },
];

// Late-arrival minutes for one day: how far the first session's in-time falls after the
// school's scheduled in-time. Matches the "late arrival only" scope already confirmed for this
// feature (mirrors, but doesn't reuse, the backend's EmployeeAttendancePermissionUtil, which
// also counts mid-day out-then-back-late gaps - out of scope here).
const lateMinutesForDay = (firstInTime, scheduledInTime) => {
  if (!firstInTime || !scheduledInTime) return 0;
  const diff = moment(firstInTime, 'HH:mm:ss').diff(moment(scheduledInTime, 'HH:mm:ss'), 'minutes');
  return diff > 0 ? diff : 0;
};

// The late-arrival forgiveness allowance (N permissions/month, each forgiving M minutes late) -
// used to be worker-only, shown on a separate "Worker Salary Impact" tab from a separate
// "Working Time Permission" tab. Merged into one "Staff Time Allowance" tab that covers both
// Teachers and Workers: the allowance/deduction math and the per-person edit both live here now.
class StaffTimeAllowancePanel extends React.Component {
  state = {
    schoolId: 0,
    activeTab: getLocalStore(ACTIVE_TAB_STORE_KEY) || 'teacher',
    employeesByRole: { teacher: [], worker: [] },
    // Starts true for both roles so the first render shows the table's loading skeleton instead
    // of the "No teachers/workers found" empty state - that empty state should only ever reflect
    // a completed, genuinely-empty fetch, not the split second before fetchEmployees resolves.
    isLoadingByRole: { teacher: true, worker: true },
    permissionConfigs: [],
    attendanceConfiguration: null,
    selectedDate: new Date(),
    isLoadingAttendance: false,
    editingEmployee: null,
  };

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool?.schoolId) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchEmployees('teacher');
        this.fetchEmployees('worker');
        this.fetchConfiguration();
        this.fetchPermissionConfigs();
        this.fetchAttendance();
      });
    }
  }

  changeTab = (event, tabIndex) => {
    const activeTab = ROLE_TABS[tabIndex].key;
    setLocalStore(ACTIVE_TAB_STORE_KEY, activeTab);
    this.setState({ activeTab });
  };

  // Teachers and Workers both fetch eagerly on mount (not lazily per tab, so switching tabs
  // feels instant) through the plain, non-redux API function into their own local state - same
  // reasoning as SchoolStaffHubPage's fetchTeachers/fetchWorkers: sharing the one employeeList
  // redux slot between two fetches in flight at once means whichever resolves second clobbers
  // the other's data.
  fetchEmployees = async role => {
    const tab = ROLE_TABS.find(t => t.key === role);
    this.setState(prev => ({ isLoadingByRole: { ...prev.isLoadingByRole, [role]: true } }));
    const list = await fetchSchoolEmployeesApi({
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
      profession: tab.profession,
    });
    this.setState(prev => ({
      employeesByRole: { ...prev.employeesByRole, [role]: list || [] },
      isLoadingByRole: { ...prev.isLoadingByRole, [role]: false },
    }));
  };

  fetchConfiguration = async () => {
    // fetchAttendanceConfigService is written as a thunk (`data => async () => {...}`) even
    // though it ignores dispatch/getState - has to be invoked as fetchAttendanceConfigService(data)()
    // rather than awaited directly, or `configuration` ends up being that inner function itself.
    const configuration = await fetchAttendanceConfigService({
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
    })();
    this.setState({ attendanceConfiguration: configuration });
  };

  fetchPermissionConfigs = async () => {
    try {
      const res = await fetchPermissionConfigsApi({ schoolId: this.state.schoolId, token: this.props.loggedUserToken });
      this.setState({ permissionConfigs: res.data || [] });
    } catch (err) {
      console.error(err?.response);
    }
  };

  // employeeId intentionally omitted - one whole-school call here covers every teacher and
  // worker's late-minutes calc at once, beating an N+1 per-employee fetch.
  fetchAttendance = async () => {
    const anchor = moment(this.state.selectedDate);
    this.setState({ isLoadingAttendance: true });
    await this.props.fetchAttendanceRange({
      schoolId: this.state.schoolId,
      fromDate: anchor.clone().startOf('month').format('YYYY-MM-DD'),
      toDate: anchor.clone().endOf('month').format('YYYY-MM-DD'),
      token: this.props.loggedUserToken,
    });
    this.setState({ isLoadingAttendance: false });
  };

  changeDate = date => this.setState({ selectedDate: date }, this.fetchAttendance);

  getStaffList = () => this.state.employeesByRole[this.state.activeTab] || [];

  findPermissionConfig = employeeId => this.state.permissionConfigs.find(c => c.employeeId === employeeId);

  openEditModal = employee => this.setState({ editingEmployee: employee });

  closeEditModal = () => this.setState({ editingEmployee: null });

  onPermissionSaved = () => this.fetchPermissionConfigs();

  buildRows = () => {
    const staffList = this.getStaffList();
    const scheduledInTime = this.state.attendanceConfiguration?.inTime;
    return staffList.map(employee => {
      const empRecords = this.props.attendanceRange.filter(a => a.employeeId === employee.employeeId);
      const actualLateMinutes = empRecords.reduce(
        (sum, a) => sum + lateMinutesForDay(a.sessions?.[0]?.inTime, scheduledInTime),
        0
      );
      const config = this.findPermissionConfig(employee.employeeId);
      const permissionCount = config?.permissionCount || 0;
      const permissionMinutes = config?.permissionMinutes || 0;
      const allowanceMinutes = permissionCount * permissionMinutes;
      // Excused is what the allowance actually covers this month, capped at how late they really
      // were - showing the full allowance here even for someone barely late (e.g. "10 min excused"
      // for a worker who was only 5 min late all month) reads as wrong even though the deduction
      // math beneath it was always correct.
      const forgivenMinutes = Math.min(actualLateMinutes, allowanceMinutes);
      const deductibleMinutes = Math.max(0, actualLateMinutes - allowanceMinutes);
      return {
        employeeId: employee.employeeId,
        name: employee.name,
        designation: employee.designation,
        actualLateMinutes,
        allowanceText: config
          ? `${allowanceMinutes} min (${permissionCount} x ${permissionMinutes} min)`
          : 'Not configured',
        allowanceCell: config ? (
          `${allowanceMinutes} min (${permissionCount} x ${permissionMinutes} min)`
        ) : (
          <span style={{ color: colors.grey3 }}>Not configured</span>
        ),
        forgivenMinutes,
        deductibleMinutes,
        updateAction: (
          <CustomButton size="small" variant="outlined" onClick={() => this.openEditModal(employee)} name="Update" />
        ),
      };
    });
  };

  renderEmptyStaffNotice = () => {
    const { activeTab } = this.state;
    return (
      !this.state.isLoadingByRole[activeTab] &&
      this.getStaffList().length === 0 && (
        <EmptyState
          icon={<PeopleOutlineIcon style={{ color: colors.accent, fontSize: 30 }} />}
          title={activeTab === 'teacher' ? 'No teachers found' : 'No workers found'}
          subtitle={
            activeTab === 'teacher'
              ? 'No employees are marked as Teaching yet. Add a teacher or set the Profession field on School Staffs.'
              : "No non-teaching staff found yet. Set an employee's Profession to Non-teaching on the Teachers " +
                'page to see them here.'
          }
        />
      )
    );
  };

  exportCsv = () => {
    const rows = this.buildRows();
    const header = [
      'Name',
      'Designation',
      'Total Minutes Late',
      'Monthly Allowance',
      'Minutes Excused',
      'Minutes To Deduct',
    ];
    const body = rows.map(r => [
      r.name,
      r.designation,
      r.actualLateMinutes,
      r.allowanceText,
      r.forgivenMinutes,
      r.deductibleMinutes,
    ]);
    downloadCsv(`${this.state.activeTab}-time-allowance-${moment(this.state.selectedDate).format('YYYY-MM')}.csv`, [
      header,
      ...body,
    ]);
  };

  render() {
    const { activeTab, selectedDate, isLoadingByRole, isLoadingAttendance, editingEmployee } = this.state;
    const activeIndex = ROLE_TABS.findIndex(tab => tab.key === activeTab);
    const hasStaff = this.getStaffList().length > 0;
    const rows = this.buildRows();
    const monthLabel = moment(selectedDate).format('MMMM YYYY');
    const note =
      `How late each ${activeTab === 'teacher' ? 'teacher' : 'worker'} was in ${monthLabel}, and how much of ` +
      'that is still on the hook for pay after their monthly late-arrival allowance covers what it can. Shown ' +
      "in minutes only, not currency — there's no way to look up a pay rate by employee from the existing " +
      'salary APIs.';

    return (
      <div>
        <Paper square style={{ marginBottom: 16 }}>
          <Tabs
            value={activeIndex}
            onChange={this.changeTab}
            TabIndicatorProps={{ style: { display: 'none' } }}
            textColor="inherit"
            variant="standard">
            {ROLE_TABS.map((tab, index) => (
              <Tab
                key={tab.key}
                label={tab.label}
                style={{
                  fontWeight: 'bold',
                  color: activeIndex === index ? colors.accent : '',
                  borderBottom: activeIndex === index ? `3px solid ${colors.accent}` : '',
                }}
              />
            ))}
          </Tabs>
        </Paper>
        <Row className="mb-2" style={{ alignItems: 'center' }}>
          <Col sm={12} md={6}>
            <span style={{ fontSize: 12, color: colors.grey3, marginRight: 8 }}>Report Month</span>
            <input
              type="date"
              className="form-control"
              style={{ display: 'inline-block', width: 'auto' }}
              value={moment(selectedDate).format('YYYY-MM-DD')}
              onChange={e => this.changeDate(moment(e.target.value, 'YYYY-MM-DD').toDate())}
            />
          </Col>
          <Col sm={12} md={6} style={{ textAlign: 'right' }}>
            {hasStaff && <CustomButton variant="outlined" size="small" onClick={this.exportCsv} name="Export CSV" />}
          </Col>
        </Row>
        {this.renderEmptyStaffNotice()}
        {(hasStaff || isLoadingByRole[activeTab]) && (
          <>
            <div style={{ color: colors.grey3, marginBottom: 10, fontSize: 12 }}>{note}</div>
            <MuiTable
              tableHeaders={[
                'Name',
                'Designation',
                'Total Minutes Late',
                'Monthly Allowance',
                'Minutes Excused',
                'Minutes To Deduct',
                'Action',
              ]}
              tableBodyData={{ content: rows }}
              bodyColumns={[
                'name',
                'designation',
                'actualLateMinutes',
                'allowanceCell',
                'forgivenMinutes',
                'deductibleMinutes',
                'updateAction',
              ]}
              idName="employeeId"
              hidePagination={true}
              isLoading={isLoadingByRole[activeTab] || isLoadingAttendance}
            />
          </>
        )}
        <PermissionConfigModal
          isOpen={!!editingEmployee}
          onClose={this.closeEditModal}
          employee={editingEmployee}
          config={editingEmployee ? this.findPermissionConfig(editingEmployee.employeeId) : null}
          schoolId={this.state.schoolId}
          token={this.props.loggedUserToken}
          onSaved={this.onPermissionSaved}
        />
      </div>
    );
  }
}

const mapStateToProps = state => ({
  loggedUserToken: state.auth.loggedUserToken,
  attendanceRange: state.attendance.attendanceRange || [],
});

const mapDispatchToProps = dispatch => ({
  fetchAttendanceRange: data => dispatch(fetchAttendanceRangeService(data)),
});

export default connect(mapStateToProps, mapDispatchToProps)(StaffTimeAllowancePanel);
