import React from 'react';
import { connect } from 'react-redux';
import moment from 'moment';
import { Badge } from 'reactstrap';
import ConfirmModal from 'views/admin/Common/ConfirmModal.jsx';
import CustomButton from 'components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable.jsx';
import { ActiveSpan, DeactiveSpan } from 'views/admin/Common/StatusBadges';
import SubTabs from '../EmployeeActivities/SubTabs.jsx';
import LeaveTypesPanel from './LeaveTypesPanel.jsx';
import {
  fetchSchoolEmployeesApi,
  fetchStaffLeavesByStatusApi,
  updateStaffLeaveStatusApi,
} from 'actions/admin/employees';
import { showToast } from 'actions/admin/auth';
import { formatLeaveDate, leaveDayCount, toLeaveDate } from 'utils/leaveDates';
import { formResMessage, getGlobalSchoolUtils } from 'utils/commonFunc';
import { store } from '../../../index';

const STATUS_TABS = [
  { tabName: 'Pending', index: 0, status: 'PENDING' },
  { tabName: 'Approved', index: 1, status: 'APPROVED' },
  { tabName: 'Rejected', index: 2, status: 'REJECTED' },
  { tabName: 'Leave types', index: 3, status: null },
];

const leaveTypeLabel = type => {
  const text = `${type || ''}`.replace(/_/g, ' ').toLowerCase();
  return text.charAt(0).toUpperCase() + text.slice(1);
};

// Leave requests teachers and workers apply for from the app, school wide: the admin approves or rejects the pending ones.
class StaffLeavesPanel extends React.Component {
  state = {
    activeTab: 0,
    leaves: { content: [] },
    employees: {},
    isLoading: false,
    pageParams: { page: 1, size: 10 },
    pendingAction: null, // { action: 'APPROVED' | 'REJECTED', leave }
    isUpdating: false,
  };

  componentDidMount() {
    this.loadEmployees();
    this.loadLeaves();
  }

  schoolId = () => getGlobalSchoolUtils()?.schoolId;

  loadEmployees = async () => {
    const base = { schoolId: this.schoolId(), token: this.props.loggedUserToken };
    const [list, teaching] = await Promise.all([
      fetchSchoolEmployeesApi(base),
      fetchSchoolEmployeesApi({ ...base, profession: 'TEACHING' }),
    ]);
    // the server's own teaching / non-teaching split names the role: teachers, and everyone else is a worker
    const teachers = new Set((teaching || []).map(employee => employee.employeeId));
    const employees = {};
    (list || []).forEach(employee => {
      employees[employee.employeeId] = {
        ...employee,
        roleLabel: teachers.has(employee.employeeId) ? 'Teacher' : 'Worker',
      };
    });
    this.setState({ employees });
  };

  loadLeaves = async (page = this.state.pageParams.page, activeTab = this.state.activeTab) => {
    this.setState({ isLoading: true });
    try {
      const leaves = await fetchStaffLeavesByStatusApi({
        schoolId: this.schoolId(),
        status: STATUS_TABS[activeTab].status,
        pageParams: { ...this.state.pageParams, page },
        token: this.props.loggedUserToken,
      });
      this.setState({ leaves, isLoading: false, pageParams: { ...this.state.pageParams, page } });
    } catch (err) {
      this.setState({ leaves: { content: [] }, isLoading: false });
      store.dispatch(showToast(formResMessage(err), 'error'));
    }
  };

  changeTab = activeTab => {
    // The "Leave types" tab is a setup page, not a list of requests.
    this.setState({ activeTab }, () => STATUS_TABS[activeTab].status && this.loadLeaves(1, activeTab));
  };

  confirmUpdate = async () => {
    const { pendingAction } = this.state;
    this.setState({ isUpdating: true });
    try {
      await updateStaffLeaveStatusApi({
        schoolId: this.schoolId(),
        employeeId: pendingAction.leave.employeeId,
        leaveId: pendingAction.leave.employeeLeaveId,
        status: pendingAction.action,
        token: this.props.loggedUserToken,
      });
      store.dispatch(showToast(pendingAction.action === 'APPROVED' ? 'Leave approved' : 'Leave rejected', 'success'));
      this.setState({ pendingAction: null, isUpdating: false });
      this.loadLeaves();
    } catch (err) {
      this.setState({ pendingAction: null, isUpdating: false });
      store.dispatch(showToast(formResMessage(err), 'error'));
    }
  };

  getTableData = () => {
    const { leaves, employees } = this.state;
    const today = moment().format('YYYY-MM-DD');
    return {
      ...leaves,
      content: (leaves.content || []).map(leave => {
        const employee = employees[leave.employeeId] || {};
        const isPending = leave.leaveStatus === 'PENDING';
        const isExpired = isPending && toLeaveDate(leave.startDate) < today;
        return {
          ...leave,
          empCode: employee.code || '--',
          empName: employee.name || `Employee ${leave.employeeId}`,
          empRole: employee.roleLabel || '--',
          leaveType: leaveTypeLabel(leave.employeeLeaveType?.leaveType) || '--',
          startDateText: formatLeaveDate(leave.startDate),
          endDateText: formatLeaveDate(leave.endDate),
          days: leave.noOfDays || leaveDayCount(leave.startDate, leave.endDate),
          actionItem: (
            <>
              {isExpired && (
                <Badge color="warning" className="ml-1 text-dark">
                  Expired
                </Badge>
              )}
              {isPending && !isExpired && (
                // one row, side by side, in the same buttons the rest of the dashboard uses
                <div
                  style={{ display: 'flex', flexWrap: 'nowrap', alignItems: 'center', gap: 8, whiteSpace: 'nowrap' }}>
                  <CustomButton
                    size="small"
                    name="Approve"
                    onClick={() => this.setState({ pendingAction: { action: 'APPROVED', leave } })}
                  />
                  <CustomButton
                    size="small"
                    variant="outlined"
                    name="Reject"
                    onClick={() => this.setState({ pendingAction: { action: 'REJECTED', leave } })}
                  />
                </div>
              )}
              {leave.leaveStatus === 'APPROVED' && <ActiveSpan status="Approved" />}
              {leave.leaveStatus === 'REJECTED' && <DeactiveSpan status="Rejected" />}
            </>
          ),
        };
      }),
    };
  };

  render() {
    const { activeTab, isLoading, pendingAction, isUpdating } = this.state;
    return (
      <>
        <SubTabs className="mb-3" subTabs={STATUS_TABS} subActive={activeTab} tabToggle={this.changeTab} />
        {!STATUS_TABS[activeTab].status ? (
          <LeaveTypesPanel />
        ) : (
          <MuiTable
            tableHeaders={[
              'Emp code',
              'Name',
              'Role',
              'Leave type',
              'Start date',
              'End date',
              'Days',
              'Reason',
              'Action',
            ]}
            tableBodyData={this.getTableData()}
            bodyColumns={[
              'empCode',
              'empName',
              'empRole',
              'leaveType',
              'startDateText',
              'endDateText',
              'days',
              'reason',
              'actionItem',
            ]}
            fetchPageData={page => this.loadLeaves(page)}
            isLoading={isLoading}
          />
        )}
        <ConfirmModal
          confirmMessage={
            pendingAction?.action === 'APPROVED'
              ? 'Are you sure you want to approve this leave?'
              : 'Are you sure you want to reject this leave?'
          }
          confirmModalOpen={!!pendingAction}
          deleteConfirm={this.confirmUpdate}
          deleteCancel={() => this.setState({ pendingAction: null })}
          loading={isUpdating}
        />
      </>
    );
  }
}

const mapStateToProps = state => ({
  loggedUserToken: state.auth.loggedUserToken,
});

export default connect(mapStateToProps)(StaffLeavesPanel);
